#!/usr/bin/env node
// Compiles contracts/*.sol with the pinned solc-js and writes src/lib/pools/generated/contracts.ts.
// The generated file is committed: the contract addresses derive from this exact bytecode (CREATE2),
// so the web build never recompiles. `--check` fails if the committed file differs from a fresh compile.

import { createRequire } from "node:module";
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);
const solc = require("solc");

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(root, "src/lib/pools/generated/contracts.ts");
const SOURCES = ["DemoUSDC.sol", "PooledFunding.sol"];
const EXPORTS = { DemoUSDC: "demoUsdc", PooledFunding: "pooledFunding" };

// "paris" keeps the bytecode free of newer opcodes, so the same build runs on Base, Ethereum and Robinhood Chain.
const SETTINGS = {
  optimizer: { enabled: true, runs: 200 },
  evmVersion: "paris",
  metadata: { bytecodeHash: "none", appendCBOR: false },
  outputSelection: { "*": { "*": ["abi", "evm.bytecode.object"] } },
};

function compile() {
  const input = {
    language: "Solidity",
    sources: Object.fromEntries(SOURCES.map((name) => [name, { content: readFileSync(join(root, "contracts", name), "utf8") }])),
    settings: SETTINGS,
  };
  const output = JSON.parse(solc.compile(JSON.stringify(input)));
  const problems = (output.errors ?? []).filter((e) => e.severity === "error" || e.severity === "warning");
  if (problems.length) {
    for (const p of problems) console.error(p.formattedMessage);
    process.exit(1);
  }
  const parts = [
    "// Generated by scripts/compile-contracts.mjs. Do not edit: run `bun run contracts` instead.",
    `// solc ${solc.version()}, optimizer 200 runs, evmVersion ${SETTINGS.evmVersion}, no metadata.`,
    "",
  ];
  for (const file of SOURCES) {
    for (const [name, artifact] of Object.entries(output.contracts[file])) {
      const id = EXPORTS[name];
      if (!id) continue;
      parts.push(`export const ${id}Abi = ${JSON.stringify(artifact.abi)} as const;`, "");
      parts.push(`export const ${id}Bytecode = "0x${artifact.evm.bytecode.object}" as const;`, "");
    }
  }
  return parts.join("\n");
}

const generated = compile();
if (process.argv.includes("--check")) {
  const current = existsSync(OUT) ? readFileSync(OUT, "utf8") : "";
  if (current !== generated) {
    console.error("src/lib/pools/generated/contracts.ts is out of date. Run `bun run contracts` and commit the result.");
    process.exit(1);
  }
  console.log("contracts: generated file matches a fresh compile");
} else {
  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(OUT, generated);
  console.log(`contracts: wrote ${OUT} (${generated.length} bytes)`);
}
